// The picture bench command line (#340): run, list, status, get and cancel like the other benches. A run on a brief
// file reads its owner photos from a folder of files named by their sha256; `get` writes the manifest, the picture
// files, the check results and the turns to an output folder. Everything is invented and generated by code.
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync, mkdirSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { after, before, beforeEach, test } from 'node:test'
import { runCli } from '../src/site-pictures/bench-cli.js'
import { fileDb } from './_db.mjs'
import {
  assignLookerDoor,
  brief,
  drain,
  KIT_REF,
  kitIndex,
  photoFolder,
  plan,
  SECRET,
  storeDir
} from './_site-pictures-bench.mjs'

const db = fileDb()
before(db.open)
beforeEach(db.reset)
after(db.close)

const opts = { skip: process.env.TEST_DATABASE_URL ? false : 'set TEST_DATABASE_URL' }
const kits = kitIndex()
after(kits.done)
const store = storeDir()
after(store.done)
const where = { index: kits.index, dir: store.dir }

const sha = (bytes) => createHash('sha256').update(bytes).digest('hex')

/** A working folder with the plan, the brief and the photo folder, as an operator would have them. */
function workFolder() {
  const cwd = mkdtempSync(path.join(tmpdir(), 'site-pictures-cli-'))
  writeFileSync(path.join(cwd, 'plan.json'), JSON.stringify(plan()))
  writeFileSync(path.join(cwd, 'brief.json'), JSON.stringify(brief()))
  mkdirSync(path.join(cwd, 'photos'))
  for (const [name, bytes] of photoFolder().files) writeFileSync(path.join(cwd, 'photos', name), bytes)
  return cwd
}

async function cli(argv, cwd) {
  // Every run needs the looker door (#343).
  await assignLookerDoor(db.pool)
  const out = []
  const err = []
  const code = await runCli(argv, {
    pool: db.pool,
    secret: SECRET,
    cwd,
    storeDir: store.dir,
    index: kits.index,
    out: (l) => out.push(l),
    err: (l) => err.push(l)
  })
  return { code, out, err }
}

const RUN = [
  'run',
  '--plan-file',
  'plan.json',
  '--kit',
  KIT_REF,
  '--brief-file',
  'brief.json',
  '--photos',
  'photos'
]

test(
  'run, status, list and get: the output folder holds the manifest, files, check results and turns',
  opts,
  async () => {
    const cwd = workFolder()
    try {
      const started = await cli([...RUN, '--by', 'tester'], cwd)
      assert.equal(started.code, 0, started.err.join('\n'))
      const id = started.out[0]
      await drain(db.pool, where)

      const status = await cli(['status', id], cwd)
      assert.equal(status.code, 0)
      assert.match(status.out.join('\n'), /state\s+succeeded \(after round 0\)/)
      assert.match(status.out.join('\n'), /site-pictures-check\/1: \d+ pass, 0 fail/)
      assert.match((await cli(['list'], cwd)).out.join('\n'), new RegExp(id))

      const got = await cli(['get', id, '--out', 'run-files'], cwd)
      assert.equal(got.code, 0, got.err.join('\n'))
      const dir = path.join(cwd, 'run-files')
      const names = readdirSync(dir)
      for (const name of [
        'site-pictures.json',
        'pictures-v1.json',
        'check-v1.json',
        'turns.jsonl',
        'run.json',
        'plan.json',
        'files.json'
      ])
        assert.ok(names.includes(name), name)
      const manifest = JSON.parse(readFileSync(path.join(dir, 'site-pictures.json'), 'utf8'))
      const placed = [...manifest.frames, ...manifest.siteSettings].filter((e) => e.file)
      for (const e of placed) {
        const bytes = readFileSync(path.join(dir, e.file))
        assert.equal(sha(bytes), e.sha256, e.frame)
      }
      assert.equal(JSON.parse(readFileSync(path.join(dir, 'check-v1.json'), 'utf8')).summary.fail, 0)
      const run = JSON.parse(readFileSync(path.join(dir, 'run.json'), 'utf8'))
      assert.deepEqual(run.photoSource, { kind: 'folder', name: 'photos', files: 8, used: 8 })
      assert.ok(!JSON.stringify(run).includes(cwd), 'no machine path is stored')
      assert.equal(readFileSync(path.join(dir, 'turns.jsonl'), 'utf8'), '')
    } finally {
      rmSync(cwd, { recursive: true, force: true })
    }
  }
)

test(
  'a photo not named by its hash refuses the run; a brief file without photos is wrong usage',
  opts,
  async () => {
    const cwd = workFolder()
    try {
      writeFileSync(path.join(cwd, 'photos', 'holiday.jpg'), Buffer.from('not named by its hash'))
      const refused = await cli(RUN, cwd)
      assert.equal(refused.code, 1)
      assert.match(refused.err.join('\n'), /SITE_PICTURES_PHOTO_HASH: The photo holiday\.jpg/)
      assert.equal((await cli(['list'], cwd)).out[0], 'no runs yet')
      const usage = await cli(RUN.slice(0, -2), cwd)
      assert.equal(usage.code, 2)
      assert.match(usage.err[0], /--photos/)
    } finally {
      rmSync(cwd, { recursive: true, force: true })
    }
  }
)

test('cancel ends a queued run nobody holds; a second run waits for none', opts, async () => {
  const cwd = workFolder()
  try {
    const id = (await cli(RUN, cwd)).out[0]
    const second = await cli(RUN, cwd)
    assert.equal(second.code, 1)
    assert.match(second.err[0], /SITE_PICTURES_RUN_ACTIVE/)
    const cancelled = await cli(['cancel', id], cwd)
    assert.deepEqual([cancelled.code, cancelled.out], [0, [`${id} cancelled`]])
    assert.match((await cli(['status', id], cwd)).out.join('\n'), /state\s+cancelled/)
  } finally {
    rmSync(cwd, { recursive: true, force: true })
  }
})
